"""ด่านฝึกและบอส ม.1 (DT-M1) · ส่วนที่ 1 · ข้อเลือกตอบเขียนให้คำตอบที่ถูกเป็นตัวแรกเสมอ แล้ว practice_content.py จะหมุนตำแหน่งให้กระจาย
ความยาวตัวเลือกพยายามให้ใกล้กัน เพื่อไม่ให้เด็กเดาจากข้อที่ยาวที่สุด (ตรวจด้วย check_lengths ใน practice_content.py)"""

def C(ctx, q, right, wrong, why): return {'t': 'choice', 'ctx': ctx, 'q': q, 'opts': [right] + wrong, 'ans': 0, 'why': why}
def B(q, right, wrong, why): return {'q': q, 'opts': [right] + wrong, 'ans': 0, 'why': why}
def PK(ctx, q, opts, ans, why): return {'t': 'pick', 'ctx': ctx, 'q': q, 'opts': opts, 'ans': ans, 'why': why}
def SO(ctx, q, cats, items, why): return {'t': 'sort', 'ctx': ctx, 'q': q, 'cats': cats, 'items': items, 'why': why}
def MA(ctx, q, pairs, why): return {'t': 'match', 'ctx': ctx, 'q': q, 'pairs': pairs, 'why': why}
def OR(ctx, q, items, why): return {'t': 'order', 'ctx': ctx, 'q': q, 'items': items, 'why': why}

